'use strict';

/*
 * FishReader 阅读 3 书源兼容插件
 * 规则引擎按 Legado_Max (commit 99e4a90759358db9db7d84a76c5bd0bb4bcf17e5)
 * 的 AnalyzeUrl / AnalyzeRule / WebBook 行为移植。
 * Upstream: https://github.com/youfengknight/Legado_Max
 * License: GNU General Public License v3.0
 */

const SOURCE_KEY = 'legado.sources.v2';
const LEGACY_SOURCE_KEY = 'legado.sources.v1';
const ACTIVE_SOURCE_KEY = 'legado.activeSource.v2';
const LEGACY_ACTIVE_SOURCE_KEY = 'legado.activeSource.v1';
const ACTIVE_SOURCE_RECORD_KEY = 'legado.activeSourceRecord.v3';
const CATALOG_CACHE_VERSION = 5;
const LEGADO_ENGINE_REVISION = 'legado-max-99e4a907-r28';
const CATALOG_CHUNK_MAXIMUM_BYTES = 384 * 1024;
// Reading's Jsoup Elements are not truncated at 1000 entries. Keep a generous
// host safety ceiling while allowing long single-page catalogues to preserve
// every chapter that fits in the host's 16 MiB HTML envelope.
const HTML_PARSE_RESULT_MAXIMUM_COUNT = 50000;
// Keep each host HTML batch bounded.  Harmony's broker accepts larger batches,
// but 2,000 requests keeps worker/IPC memory predictable while still letting
// one completed batch immediately feed the next one for very large catalogues.
const HTML_PARSE_BATCH_CHUNK_SIZE = 2000;
// A single aggregate endpoint can return several thousand rows. Reading keeps
// search results as a transient list; carrying hundreds of per-row JS rule
// evaluations through one plugin invocation only increases latency and can hit
// the isolated-runtime deadline before the first usable result reaches the UI.
let activeExecutionState = {};
const sharedJsLibMemoryCache = new Map();
const normalizedJsLibMemoryCache = new Map();
const jsLibProgramMemoryCache = new Map();
const normalizedSourceRuleMemoryCache = new WeakMap();
// Rules run with a fresh scope, but a source's jsLib itself is immutable during
// a search. Cache the compiled wrapper, not the scope or any rule state: this
// preserves Reading's per-rule isolation while avoiding repeated parsing of a
// large helper library once per returned book.
const compiledJsRuleRunnerMemoryCache = new Map();
const COMPILED_JS_RULE_RUNNER_CACHE_LIMIT = 128;
const jsLibRuleDependencyMemoryCache = new Map();
const javaSystemPropertiesCompat = new Map();
// A few older sites omit the charset from Content-Type and only declare it in
// the HTML meta tag.  Keep the detected value per origin so subsequent catalog
// and chapter requests can ask the host for raw bytes directly instead of
// parsing a UTF-8-decoded (and already corrupted) string.
const responseEncodingMemory = new Map();

function text(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    if (value.__legadoHtmlNode === true && typeof value.outerHtml === 'function') {
      return value.outerHtml();
    }
    // Jsoup Elements is list-shaped, but Java's String(Elements) returns its
    // element markup.  Preserve that explicitly supplied collection coercion
    // before treating ordinary JavaScript arrays as JSON data.  This is also
    // how SourceRule receives the final value from a JavaScript content rule.
    if (Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, 'toString') &&
        value.toString !== Array.prototype.toString) {
      try {
        const rendered = value.toString();
        if (typeof rendered === 'string' && rendered !== '[object Object]') return rendered;
      } catch (_) {}
    }
    // Java compatibility wrappers (notably java.lang.String) intentionally
    // expose toString/valueOf methods but have no enumerable data. Serializing
    // them first turns their value into "{}" and breaks Base64/crypto rules.
    if (!Array.isArray(value) && typeof value.toString === 'function') {
      try {
        const rendered = value.toString();
        if (typeof rendered === 'string' && rendered !== '[object Object]') return rendered;
      } catch (_) {}
    }
    try { return JSON.stringify(value); } catch (_) {}
  }
  return String(value);
}

// AnalyzeRule template substitutions are scalar text operations.  A JsonPath
// expression can yield a one-item (or multi-item) list, but Reading flattens
// that list through its getString semantics before it is embedded in a URL or
// another rule.  JSON.stringify() would instead produce "[123]", turning a
// valid template URL such as /chapter/{{ $..bookId }} into /chapter/[123].
function templateText(value) {
  return Array.isArray(value) ? value.map(item => text(item)).join('\n') : text(value);
}

// Kotlin Reading's String.isTrue() treats every non-empty value as true except
// false/no/not/0.  This matters for JSON values too: an existing empty array
// is represented as "[]" by the JSON engine and therefore remains truthy for
// rules such as `isVolume: region`.  Keep that distinction from a missing
// field, which is an empty string and false.
function legadoBoolean(value) {
  let rendered;
  if (Array.isArray(value)) {
    try { rendered = JSON.stringify(value); } catch (_) { rendered = String(value); }
  } else {
    rendered = text(value);
  }
  const normalized = text(rendered).trim();
  return normalized.length > 0 && normalized !== 'null' &&
    !/^(?:false|no|not|0|0\.0)$/i.test(normalized);
}

function directJsonRuleValue(rule, input) {
  let path = text(rule).trim().replace(/^@json:/i, '');
  if (path.startsWith('$.')) path = path.slice(2);
  else if (path.startsWith('$')) path = path.slice(1);
  if (!/^[A-Za-z_$][\w$-]*(?:\.[A-Za-z_$][\w$-]*)*$/.test(path) ||
      input === null || input === undefined || typeof input !== 'object') {
    return { matched: false, value: undefined };
  }
  let current = input;
  for (const key of path.split('.')) {
    if (current === null || current === undefined || typeof current !== 'object' ||
        !Object.prototype.hasOwnProperty.call(current, key)) {
      return { matched: false, value: undefined };
    }
    current = current[key];
  }
  return { matched: true, value: current };
}

// Catalogue rows returned by JSON APIs are already Java Maps in Reading.
// AnalyzeByJSonPath therefore resolves a plain field or a literal template
// directly against that row; it does not send every chapter back through the
// complete SourceRule analyser. Large catalogues commonly contain thousands of
// rows, so preserve that inexpensive path when the rule is provably limited to
// simple JSON fields/templates. Any JS, replacement, variable or selector rule
// continues through ruleValue below.
function directCatalogJsonRuleValue(rule, input) {
  const raw = text(rule).trim();
  if (!raw || input === null || input === undefined || typeof input !== 'object' ||
      /(?:##|<js>|@(?:js|webjs|put|get|css|xpath|json):)/i.test(raw)) {
    return { matched: false, value: undefined };
  }
  const direct = directJsonRuleValue(raw, input);
  if (direct.matched) return direct;
  if (!raw.includes('{{$.') && !raw.includes('{$.')) {
    return { matched: false, value: undefined };
  }
  let matchedTemplate = false;
  const resolve = (_all, doublePath, singlePath) => {
    matchedTemplate = true;
    const selected = directJsonRuleValue('$.' + text(doublePath || singlePath), input);
    return selected.matched ? templateText(selected.value) : '';
  };
  const value = raw.replace(/\{\{\$\.([A-Za-z_$][\w$-]*(?:\.[A-Za-z_$][\w$-]*)*)\}\}|\{\$\.([A-Za-z_$][\w$-]*(?:\.[A-Za-z_$][\w$-]*)*)\}/g,
    resolve);
  if (!matchedTemplate || value.includes('{{') || value.includes('{$.')) {
    return { matched: false, value: undefined };
  }
  return { matched: true, value };
}

function normalizedBookTypes(value) {
  const result = [];
  text(value).split(/[，,、|/·\s]+/).forEach(item => {
    const type = text(item).trim();
    if (type && type !== '连载' && type !== '完结' && type !== '停更' && !result.includes(type)) {
      result.push(type);
    }
  });
  return result.slice(0, 32);
}

function normalizedPublicationStatus(value) {
  const source = text(value);
  if (source.includes('完结')) return '完结';
  if (source.includes('停更')) return '停更';
  if (source.includes('连载')) return '连载';
  return '';
}

function object(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

const INTERNAL_SOURCE_KEY = '__fishreaderSourceKey';

function attachSourceKey(source, key) {
  const target = object(source);
  const value = text(key).trim();
  if (!value) return target;
  try {
    Object.defineProperty(target, INTERNAL_SOURCE_KEY, {
      value, configurable: true, enumerable: false, writable: true
    });
  } catch (_) {
    target[INTERNAL_SOURCE_KEY] = value;
  }
  return target;
}

function sourceRecordKey(source) {
  return text(source && source[INTERNAL_SOURCE_KEY]).trim() ||
    text(source && (source.bookSourceUrl || source.bookSourceName)).trim();
}

function stableSourceBase(key) {
  const match = text(key).trim().match(/^(.*)#fishreader=[0-9a-f]{8}$/i);
  return match ? text(match[1]).trim() : '';
}

function normalizeSingleQuotedJson(value) {
  const raw = text(value);
  let output = '';
  let quote = '';
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (!quote) {
      if (character === "'") {
        quote = "'";
        output += '"';
      } else {
        if (character === '"') quote = '"';
        output += character;
      }
      continue;
    }
    if (escaped) {
      if (quote === "'" && character === "'") output += "'";
      else if (quote === "'" && character === '"') output += '\\"';
      else output += '\\' + character;
      escaped = false;
      continue;
    }
    if (character === '\\') {
      escaped = true;
      continue;
    }
    if (character === quote) {
      output += '"';
      quote = '';
      continue;
    }
    output += quote === "'" && character === '"' ? '\\"' : character;
  }
  if (escaped) output += '\\';
  if (quote) throw new Error('登录界面配置包含未闭合字符串');
  return output;
}

function normalizeLenientLoginUiJson(value) {
  const raw = normalizeSingleQuotedJson(value);
  let output = '';
  let quoted = false;
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quoted) {
      output += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') {
      quoted = true;
      output += character;
      continue;
    }
    if (character !== '{' && character !== ',') {
      output += character;
      continue;
    }
    output += character;
    let cursor = index + 1;
    while (cursor < raw.length && /\s/.test(raw[cursor])) {
      output += raw[cursor];
      cursor++;
    }
    if (cursor >= raw.length || !/[A-Za-z_$]/.test(raw[cursor])) {
      index = cursor - 1;
      continue;
    }
    const keyStart = cursor;
    cursor++;
    while (cursor < raw.length && /[A-Za-z0-9_$]/.test(raw[cursor])) cursor++;
    const keyEnd = cursor;
    while (cursor < raw.length && /\s/.test(raw[cursor])) cursor++;
    if (raw[cursor] !== ':') {
      output += raw.slice(keyStart, cursor);
      index = cursor - 1;
      continue;
    }
    output += '"' + raw.slice(keyStart, keyEnd) + '"' + raw.slice(keyEnd, cursor) + ':';
    index = cursor;
  }

  let normalized = '';
  quoted = false;
  escaped = false;
  for (let index = 0; index < output.length; index++) {
    const character = output[index];
    if (quoted) {
      normalized += character;
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') {
      quoted = true;
      normalized += character;
      continue;
    }
    if (character === ',') {
      let cursor = index + 1;
      while (cursor < output.length && /\s/.test(output[cursor])) cursor++;
      if (output[cursor] === '}' || output[cursor] === ']') continue;
    }
    normalized += character;
  }
  return normalized;
}

function parseLoginUi(value) {
  const raw = text(value).trim();
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    const parsed = JSON.parse(normalizeLenientLoginUiJson(raw));
    return Array.isArray(parsed) ? parsed : [];
  }
}

function legadoRuleObject(value, primitiveField) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const raw = text(value);
  if (!raw) return {};
  let parsed = raw;
  for (let depth = 0; depth < 3 && typeof parsed === 'string'; depth++) {
    try {
      parsed = JSON.parse(parsed);
    } catch (_) {
      const loose = legadoLooseJsonObject(parsed);
      if (Object.keys(loose).length > 0 || /^\s*\{\s*\}\s*$/.test(parsed)) parsed = loose;
      else break;
    }
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  }
  const output = {};
  output[primitiveField] = typeof parsed === 'string' ? parsed : raw;
  return output;
}

function sourceRuleTemplate(source) {
  const item = object(source);
  const currentNames = ['ruleSearch', 'ruleExplore', 'ruleBookInfo', 'ruleToc', 'ruleContent'];
  const legacyNames = ['searchRule', 'exploreRule', 'bookInfoRule', 'tocRule', 'contentRule'];
  const current = currentNames.some(name => item[name] !== undefined && item[name] !== null);
  const legacy = !current && legacyNames.some(name => item[name] !== undefined && item[name] !== null);
  return current ? {
    version: 'current', search: legadoRuleObject(item.ruleSearch, 'bookList'),
    explore: legadoRuleObject(item.ruleExplore, 'bookList'),
    bookInfo: legadoRuleObject(item.ruleBookInfo, 'name'),
    toc: legadoRuleObject(item.ruleToc, 'chapterList'),
    content: legadoRuleObject(item.ruleContent, 'content'),
    bookList: object(item.ruleBookList)
  } : {
    version: legacy ? 'legacy' : 'current', search: legadoRuleObject(item.searchRule, 'bookList'),
    explore: legadoRuleObject(item.exploreRule, 'bookList'),
    bookInfo: legadoRuleObject(item.bookInfoRule, 'name'),
    toc: legadoRuleObject(item.tocRule, 'chapterList'),
    content: legadoRuleObject(item.contentRule, 'content'),
    bookList: object(item.bookListRule)
  };
}

function hasRuleValue(value) {
  if (value === undefined || value === null) return false;
  if (typeof value === 'string') return value.trim().length > 0;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === 'object') return Object.keys(value).length > 0;
  return true;
}

function bookListRulesFor(source, entrypoint) {
  const template = sourceRuleTemplate(source);
  if (entrypoint !== 'explore') return template.search;
  const explore = object(template.explore);
  if (!hasRuleValue(explore.bookList)) return template.search;

  // Reading keeps the explore list selector separate, but many sources only
  // override that selector (or a couple of fields). Treat the remaining
  // fields as inherited from ruleSearch instead of passing an incomplete
  // ruleExplore object to the mapper.
  const merged = Object.assign({}, object(template.search));
  Object.keys(explore).forEach(key => {
    if (hasRuleValue(explore[key])) merged[key] = explore[key];
  });
  return merged;
}

function sourceNetworkUrl(source) {
  // Reading normalizes the source origin before resolving relative rule URLs.
  // Imported source packs often carry display whitespace before an optional
  // `#tag` suffix; keep that metadata out of the transport URL.
  return text(source && source.bookSourceUrl).trim().replace(/#.*$/, '').trim();
}

function sourceCookieProbeUrl(source) {
  const declared = sourceNetworkUrl(source).trim();
  if (/^https?:\/\//i.test(declared)) return declared;
  // Reading permits a logical source identifier in bookSourceUrl. In that
  // case it must not be passed to the host Cookie API as though it were a URL.
  // Resolve a real operational origin from the rules instead. jsLib is checked
  // before discover/login HTML because aggregate sources commonly keep their
  // active service list there while explore/login contain unrelated sites.
  const candidates = [source && source.searchUrl, source && source.jsLib,
    source && source.exploreUrl, source && source.loginUrl, source && source.header];
  for (const candidate of candidates) {
    const match = text(candidate).match(/https?:\/\/[^\s"'<>},]+/i);
    if (!match) continue;
    const origin = match[0].match(/^(https?:\/\/[^/?#]+)/i);
    if (origin) return origin[1] + '/';
  }
  return '';
}

function resultSourceName(value) {
  const item = object(value);
  const raw = item.sourceName || item.source_name || item.source || item.originName ||
    item.origin_name || item.origin || item.siteName || item.site_name || item.site;
  if (raw && typeof raw === 'object') return text(raw.name || raw.title || raw.id).trim().slice(0, 512);
  return text(raw).trim().slice(0, 512);
}

function resultSourceDisplayName(source, value) {
  const parent = text(source && (source.bookSourceName || source.bookSourceUrl)).trim().slice(0, 512);
  const child = resultSourceName(value);
  if (!child || child === parent || parent.includes(child)) return parent || child;
  if (child.includes(parent)) return child;
  return `${parent}•${child}`;
}

function leadingJsonValue(value) {
  const raw = text(value).trim();
  if (!raw || (!raw.startsWith('{') && !raw.startsWith('['))) return '';
  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') quoted = true;
    else if (character === '{' || character === '[') depth++;
    else if (character === '}' || character === ']') {
      depth--;
      if (depth === 0) return raw.slice(0, index + 1);
      if (depth < 0) return '';
    }
  }
  return '';
}

function legadoBookTypeForSource(source) {
  const sourceType = Number(source && source.bookSourceType);
  if (sourceType === 1) return 32;
  if (sourceType === 2) return 64;
  if (sourceType === 3) return 8 | 128;
  if (sourceType === 4) return 4;
  return 8;
}

function legadoMediaType(source, book, raw) {
  const sourceType = Number(source && source.bookSourceType);
  const bookType = Number(book && book.type);
  // Legado_Max derives a Book's content bit from BookSourceType, but aggregate
  // rules may update book.type while evaluating a row. The mutable Book value
  // is therefore authoritative once present; source type is only its initial
  // value/fallback. BookType is a bit mask: web-file is intercepted before any
  // reader opens; the remaining reader order mirrors BookInfoActivity.
  if (Number.isFinite(bookType)) {
    if ((bookType & 128) !== 0) return 'file';
    if ((bookType & 32) !== 0) return 'audiobook';
    if ((bookType & 4) !== 0) return 'video';
    if ((bookType & 64) !== 0) return 'comic';
    if ((bookType & 8) !== 0) return 'text';
    if (bookType === 1) return 'audiobook';
    if (bookType === 2) return 'comic';
    if (bookType === 3) return 'file';
    // Zero and the legacy generic value only mean that no specialized
    // BookType bit was persisted. Aggregation rules can still carry the real
    // media kind on their detail/chapter payload (for example tab=听书), so do
    // not return before checking those explicit markers below.
  }
  if (sourceType === 1) return 'audiobook';
  if (sourceType === 2) return 'comic';
  if (sourceType === 3) return 'file';
  if (sourceType === 4) return 'video';
  let data = object(raw);
  if (Object.keys(data).length === 0 && typeof raw === 'string') {
    const rendered = text(raw).trim();
    // Most JSON catalogue/detail responses are one complete document. Let the
    // engine's JSON parser consume that directly before falling back to the
    // boundary scanner used for JSON followed by script/markup. Walking a
    // multi-megabyte catalogue character by character in the plugin VM can
    // otherwise dominate the whole catalogue request even though Reading maps
    // the same response immediately.
    try { data = object(JSON.parse(rendered)); } catch (_) {
      const json = leadingJsonValue(rendered);
      if (json) {
        try { data = object(JSON.parse(json)); } catch (_) {}
      }
    }
  }
  // Some Reading 3 sources persist BookType on the raw detail object (or use
  // snake_case names) instead of assigning book.type.  Treat those explicit
  // bit flags the same way as the Android runtime; this is source-agnostic and
  // keeps audio classification available after a detail/catalog round trip.
  const bitFlagValues = [
    source && source.bookType, source && source.book_type,
    book && book.bookType, book && book.book_type,
    data.bookType, data.book_type, data.book_type_id, data.mediaTypeId
  ].map(value => Number(value)).filter(value => Number.isFinite(value));
  if (bitFlagValues.some(value => (value & 128) !== 0 || value === 3)) return 'file';
  if (bitFlagValues.some(value => (value & 32) !== 0)) return 'audiobook';
  if (bitFlagValues.some(value => (value & 4) !== 0)) return 'video';
  if (bitFlagValues.some(value => (value & 64) !== 0)) return 'comic';
  const explicitTab = text(data.tab || (book && book.tab)).trim();
  if (explicitTab === '听书') return 'audiobook';
  if (explicitTab === '漫画') return 'comic';
  if (explicitTab === '短剧') return 'video';
  if (explicitTab === '小说') return 'text';
  // Detail/catalog snapshots persist the normalized media type separately
  // from the original source response.  Reading's runtime carries that
  // value into chapter execution; do the same instead of requiring every
  // source to repeat an audio marker in its raw chapter payload.
  const marker = [source && source.mediaType, source && source.media_type,
    book && book.mediaType, book && book.media_type, data.mediaType]
    .map(value => text(value)).join(' ');
  if (/(?:听书|有声|音频|audio|audiobook)/i.test(marker)) return 'audiobook';
  if (/(?:漫画|图片|comic|image)/i.test(marker)) return 'comic';
  if (/(?:短剧|视频|video)/i.test(marker)) return 'video';
  if (/(?:文件|下载|webfile|web_file)/i.test(marker)) return 'file';
  return 'text';
}

function chapterExecutionMediaType(source, input, book, chapter) {
  const request = object(input);
  const savedChapter = object(chapter);
  const rawChapter = object(savedChapter.raw);
  // Classify the concrete chapter before consulting the persisted book. A
  // source may reuse one book snapshot across text/video/audio tabs, and an
  // old text/video bit on that snapshot must not hide tab=听书 (or the
  // normalized chapter mediaType) carried by the selected chapter.
  const chapterValue = Object.assign({}, rawChapter, savedChapter);
  // `BookChapter` has no Book.type. API chapter rows frequently use a plain
  // `type` field for a chapter/category discriminator (for example 1 for a
  // normal free text chapter). Do not reinterpret that transport field as a
  // Reading BookType bit while deciding which reader to open.
  if (Object.prototype.hasOwnProperty.call(rawChapter, 'type')) delete chapterValue.type;
  const requestedMediaType = text(request.mediaType || request.media_type ||
    request.contentType || request.content_type).trim();
  // The host persists the normalized media type when the user adds the book.
  // Treat that explicit playback context the same way Reading treats Book.type:
  // it is authoritative for this execution even if an older/raw aggregation
  // snapshot still carries tab=小说.
  if (/^(?:audio|audiobook)$/i.test(requestedMediaType)) return 'audiobook';
  if (/^(?:comic|image)$/i.test(requestedMediaType)) return 'comic';
  if (/^video$/i.test(requestedMediaType)) return 'video';
  if (/^text$/i.test(requestedMediaType)) return 'text';
  if (requestedMediaType) chapterValue.mediaType = requestedMediaType;
  if (!text(chapterValue.tab).trim()) chapterValue.tab = text(rawChapter.tab || request.tab).trim();
  const chapterType = legadoMediaType(source, chapterValue,
    Object.keys(rawChapter).length > 0 ? rawChapter : savedChapter.raw);
  if (chapterType !== 'text') return chapterType;
  return legadoMediaType(source, book, book && book.raw);
}

function mediaHeaders(sample) {
  const headers = Object.assign({}, object(sample.headers || sample.header));
  const referer = text(sample.referer || sample.referrer).trim();
  if (referer && !Object.keys(headers).some(key => key.toLowerCase() === 'referer')) {
    headers.Referer = referer;
  }
  const normalized = {};
  Object.keys(headers).slice(0, 64).forEach(key => {
    const name = text(key).trim();
    const value = text(headers[key]).trim();
    if (name && value) normalized[name] = value.slice(0, 8192);
  });
  return normalized;
}

function normalizeMediaText(value) {
  return text(value).trim()
    .replace(/\\u([0-9a-f]{4})/gi, (_all, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/\\\//g, '/')
    .replace(/\\"/g, '"')
    .replace(/&amp;/gi, '&');
}

function isAudioMediaUrl(value) {
  const url = normalizeMediaText(value);
  return /\.(?:mp3|m4a|aac|ogg|opus|flac|wav|ape|wma)(?:[?#]|$)/i.test(url) ||
