function structuredChapterFromCandidates(values, mediaTypeHint, baseUrl = '', defaultHeaders = {}) {
  const primaryRaw = text(values[0]).trim();
  const primary = structuredChapterContent(primaryRaw, mediaTypeHint, baseUrl, defaultHeaders, true);
  if (primary && primary.contentType === 'text') return primary;
  if (primary && primary.contentType === 'audio' &&
      (/,\s*\{/.test(primaryRaw) || /[?&](?:tone|voice|speaker|narrator)=/i.test(primaryRaw))) {
    // The evaluated source rule may have attached a selected tone or explicit
    // player headers to the URL.  Preserve that deliberate result instead of
    // replacing it with the raw endpoint envelope below.
    return primary;
  }
  // A normal source rule may already have produced plain text/HTML. Do not
  // replace it with an unrelated text field from the raw HTTP envelope.
  if (primaryRaw && !leadingJsonValue(primaryRaw) && mediaTypeHint !== 'audiobook') return primary;
  let fallback = primary;
  let audioFallback = primary && primary.contentType === 'audio' &&
    Array.isArray(primary.mediaUrls) && primary.mediaUrls.length > 0 ? primary : null;
  for (let index = 1; index < values.length; index++) {
    const value = values[index];
    if (!text(value).trim()) continue;
    // The raw chapter HTTP response may use a generic `url` field for a signed
    // stream without an extension. Trust that immediate response, but do not
    // trust generic URLs in persisted book/chapter metadata; those commonly
    // point to covers or detail pages.
    const parsed = structuredChapterContent(value, mediaTypeHint, baseUrl, defaultHeaders,
      index === 1);
    if (!parsed) continue;
