  if (mediaTypeHint !== 'audiobook' || !text(content).trim()) return null;
  const parsed = structuredChapterContent(content, mediaTypeHint, baseUrl, defaultHeaders, true);
  if (!(parsed && parsed.contentType === 'audio' &&
      Array.isArray(parsed.mediaUrls) && parsed.mediaUrls.length > 0)) return null;
