function httpTtsBaseUrl(record) {
  const combined = [record && record.url, record && record.loginUrl, record && record.header]
    .map(value => text(value)).join('\n');
  const match = combined.match(/https?:\/\/[^\s"'<>},]+/i);
  if (!match) return '';
  const value = match[0].replace(/\\[nrt].*$/, '');
  const origin = value.match(/^(https?:\/\/[^/]+)/i);
  return origin ? origin[1] + '/' : value;
