    "SELECT source_key, name, source_json FROM legado_sources WHERE enabled = 1 AND " +
    "json_extract(source_json, '$.bookSourceUrl') = ? ORDER BY import_order ASC LIMIT 1",
    [sourceKey], 1);
  if (declared && Array.isArray(declared.rows) && declared.rows.length > 0) {
    const row = declared.rows[0];
    const source = databaseSourceFromRow(row);
    if (source === null || !text(source[capability]).trim()) return null;
    return { sourceKey: text(row.source_key || source.bookSourceUrl || source.bookSourceName),
      name: text(row.name || source.bookSourceName || source.bookSourceUrl), groups: sourceGroups(source), mediaType: legadoMediaType(source) };
  }
  for (let offset = 0; ; offset += 500) {
    const result = await databaseQueryAsync(
      'SELECT source_key, name, source_json FROM legado_sources WHERE enabled = 1 ' +
      'ORDER BY import_order ASC LIMIT 500 OFFSET ' + offset, [], 500);
    if (!result || !Array.isArray(result.rows)) return null;
    for (const row of result.rows) {
      const source = databaseSourceFromRow(row);
      if (source === null) continue;
      if (text(row.source_key).trim() !== sourceKey &&
          text(source.bookSourceUrl).trim() !== sourceKey) continue;
      if (!text(source[capability]).trim()) return null;
      return {
        sourceKey: text(row.source_key || source.bookSourceUrl || source.bookSourceName),
        name: text(row.name || source.bookSourceName || source.bookSourceUrl),
        groups: sourceGroups(source), mediaType: legadoMediaType(source)
      };
    }
    if (result.rows.length < 500) break;
  }
  return null;
}

function isGrantedNetworkDomain(value) {
  const domain = text(value).trim().toLowerCase();
  return domain.length > 0 && domain.length <= 253 &&
    /^(?:\*\.)?(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)(?:\.(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?))*$/.test(domain);
}

function sourceStringValues(value, output) {
  if (typeof value === 'string') { output.push(value); return; }
  if (Array.isArray(value)) { value.forEach(item => sourceStringValues(item, output)); return; }
  if (!value || typeof value !== 'object') return;
  Object.keys(value).forEach(key => sourceStringValues(value[key], output));
}

function balancedSourceArray(value, start) {
  let depth = 0, quote = '', escaped = false;
  for (let index = start; index < value.length; index++) {
    const char = value[index];
    if (escaped) { escaped = false; continue; }
    if (char === '\\') { escaped = true; continue; }
    if (quote) { if (char === quote) quote = ''; continue; }
    if (char === '"' || char === "'" || char === '`') { quote = char; continue; }
    if (char === '[') depth++;
    else if (char === ']' && --depth === 0) return value.slice(start + 1, index);
  }
  return '';
}

function staticDynamicDomainLabels(sourceText) {
  const labels = [];
  const field = /(?:^|[,{;\\n])\s*["']?([A-Za-z_$][\w$]*)["']?\s*:\s*\[/g;
  let match;
  while ((match = field.exec(sourceText)) !== null) {
    if (!/(?:domain|host|server)/i.test(match[1])) continue;
    const content = balancedSourceArray(sourceText, field.lastIndex - 1);
    if (!content) continue;
    const quoted = /["']([A-Za-z0-9-]{1,63})["']/g;
    let label;
    while ((label = quoted.exec(content)) !== null) {
      const value = label[1].toLowerCase();
      if (!/^(?:get|post|put|delete|true|false|null|utf8?|json|html|http|https)$/i.test(value) &&
          !labels.includes(value)) labels.push(value);
    }
  }
  return labels;
}

function domainsFromSource(source) {
  let serialized = '';
  try { serialized = JSON.stringify(source); } catch (_) { return []; }
  const urls = serialized.match(/https?:\/\/[A-Za-z0-9.-]+(?::\d+)?/gi) || [];
  const domains = [];
  for (const raw of urls) {
    const match = raw.match(/^https?:\/\/([^/:?#]+)/i);
    const domain = text(match && match[1]).trim().toLowerCase().replace(/\.+$/, '');
    if (isGrantedNetworkDomain(domain) && !domains.includes(domain)) domains.push(domain);
  }
  serialized.replace(/["']?dnsIp["']?\s*:\s*["']([^"']+)["']/gi, (_all, raw) => {
    text(raw).split(/[\s,;]+/).forEach(value => {
      const address = value.trim().replace(/^\[|\]$/g, '').toLowerCase();
      if ((/^(?:\d{1,3}\.){3}\d{1,3}$/.test(address) || /^[0-9a-f:]+$/i.test(address)) &&
          isGrantedNetworkDomain(address) &&
          !domains.includes(address)) domains.push(address);
    });
    return _all;
  });
  // A Reading source may construct a request host from a static candidate list
  // (for example `https://api.${domain}.com`) and catch failed attempts inside
  // its own rule.  The catch prevents FishReader from seeing a denied request
  // and asking for that domain later.  Discover only labels declared in a
  // domain/host/server list and only when a matching URL template is present;
  // this grants no wildcard and does not infer domains from arbitrary strings.
  const strings = [];
  sourceStringValues(source, strings);
  const sourceText = strings.join('\n');
  const labels = staticDynamicDomainLabels(sourceText);
  const template = /https?:\/\/([A-Za-z0-9.-]*)\$\{[A-Za-z_$][\w$]*\}([A-Za-z0-9.-]*)/g;
  let hostTemplate;
  while ((hostTemplate = template.exec(sourceText)) !== null) {
    labels.forEach(label => {
      const domain = (hostTemplate[1] + label + hostTemplate[2]).toLowerCase().replace(/\.+$/, '');
      if (isGrantedNetworkDomain(domain) && !domains.includes(domain)) domains.push(domain);
    });
  }
  return domains;
}

function permissionGroup(source, sourceKey, name) {
  const domains = domainsFromSource(source);
  const title = text(name || source.bookSourceName || source.bookSourceUrl || '未命名书源');
  const key = text(sourceKey || source.bookSourceUrl || source.bookSourceName || `source:${title}`);
  return {
    key,
    title,
    domains
  };
}

function databasePermissionGroups() {
  const groups = [];
  for (let offset = 0; ; offset += 500) {
    const result = databaseQuery(
      'SELECT source_key, name, source_json FROM legado_sources ' +
      'ORDER BY import_order ASC LIMIT 500 OFFSET ' + offset, [], 500);
    if (!result || !Array.isArray(result.rows)) return null;
    for (const row of result.rows) {
      let source = {};
      try { source = object(JSON.parse(text(row.source_json))); } catch (_) { continue; }
      groups.push(permissionGroup(source, row.source_key, row.name));
    }
    if (result.rows.length < 500) break;
  }
  return groups;
}

function sourceConfig() {
  const raw = Object.prototype.hasOwnProperty.call(activeExecutionState, 'sourceVariable') ?
    activeExecutionState.sourceVariable : reader.source.getVariable();
  if (raw && typeof raw.then === 'function') return {};
  if (!raw) return {};
  try { return object(JSON.parse(raw)); } catch (_) { return {}; }
}

function importedSources() {
  const stored = reader.storage.get(SOURCE_KEY) || reader.storage.get(LEGACY_SOURCE_KEY);
  return Array.isArray(stored) ? stored : [];
}

async function importedSourcesAsync() {
  const current = await Promise.resolve(reader.storage.get(SOURCE_KEY));
  const legacy = current || await Promise.resolve(reader.storage.get(LEGACY_SOURCE_KEY));
  return Array.isArray(legacy) ? legacy : [];
