    return object(activeRecord);
  }
  const databaseSource = databaseFirstEnabledSource();
  if (databaseSource) return databaseSource;
  const sources = importedSources().filter(item => item.enabled !== false);
  if (sources.length === 0) throw new Error('请先打开插件页面导入阅读书源');
  const activeUrl = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
    reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
