}

function stored(key) {
  return object(storageGet(key));
}

function storageGet(key) {
  const normalized = text(key);
  if (activeExecutionState.exploreVariables &&
      Object.prototype.hasOwnProperty.call(activeExecutionState.exploreVariables, normalized)) {
    return activeExecutionState.exploreVariables[normalized];
  }
  const values = object(activeExecutionState.storageValues);
  if (Object.prototype.hasOwnProperty.call(values, normalized)) return values[normalized];
  const value = reader.storage.get(normalized);
  // ArkWeb's bridge is synchronous, while Android JavaScriptSandbox exposes
  // host functions as Promises. Async entrypoints preload the values they need;
  // never let a Promise masquerade as stored plugin data in compatibility code.
  if (value && typeof value.then === 'function') return undefined;
  if (activeExecutionState.storageValues) activeExecutionState.storageValues[normalized] = value;
  return value;
}

function storageSet(key, value) {
  const normalized = text(key);
  if (activeExecutionState.exploreVariables &&
      Object.prototype.hasOwnProperty.call(activeExecutionState.exploreVariables, normalized)) {
    activeExecutionState.exploreVariables[normalized] = value;
    return true;
  }
  if (activeExecutionState.storageValues) activeExecutionState.storageValues[normalized] = value;
  const pending = reader.storage.set(normalized, value);
  if (pending && typeof pending.then === 'function' && Array.isArray(activeExecutionState.pendingWrites)) {
    activeExecutionState.pendingWrites.push(pending);
  }
  return pending;
}

function storageRemoveBatch(keys) {
  const normalized = [...new Set((Array.isArray(keys) ? keys : [])
    .map(key => text(key)).filter(Boolean))];
  if (normalized.length === 0) return true;
  if (!reader.storage || typeof reader.storage.removeBatch !== 'function') return false;
  if (activeExecutionState.storageValues) {
    normalized.forEach(key => { delete activeExecutionState.storageValues[key]; });
  }
  let result = true;
  for (let offset = 0; offset < normalized.length; offset += 5000) {
    const pending = reader.storage.removeBatch(normalized.slice(offset, offset + 5000));
    if (pending && typeof pending.then === 'function' && Array.isArray(activeExecutionState.pendingWrites)) {
      activeExecutionState.pendingWrites.push(pending);
    }
    result = pending;
  }
  return result;
}

function utf8ByteLength(value) {
  try { return unescape(encodeURIComponent(text(value))).length; } catch (_) {
    return text(value).length * 3;
  }
}

function firstData(value) {
  const source = object(value);
  return source.data && !Array.isArray(source.data) ? object(source.data) : source;
}

function bookKey(item) {
  return 'legado.book.' + encodeURIComponent(text(item.source || 'source')).slice(0, 80) + '.' +
    encodeURIComponent(text(item.book_id || item.id)).slice(0, 160);
}

function chapterKey(bookIdentity, item, index) {
