function detailResult(identity, detail, source, rules, result, fieldEnv) {
  const kind = optionalRuleText(source, rules.kind, result, fieldEnv, text(detail.kind));
  // Keep the concrete URLs produced by BookInfo.  The book key is an internal
  // storage identity, not a navigable document URL.  Returning that identity
  // here used to make the host pass a hash-like key into the following catalog
  // call, which only worked while the previous detail execution's private
  // storage happened to be available.
  const bookUrl = text(detail.bookUrl) || identity;
  const tocUrl = text(detail.tocSourceUrl) || bookUrl || identity;
  return { bookKey: identity, title: detail.title || '未命名书籍', author: detail.author,
    sourceName: text(detail.sourceName),
    intro: detail.intro, coverUrl: detail.coverUrl, bookUrl, tocUrl,
    kind, types: normalizedBookTypes(kind), publicationStatus: normalizedPublicationStatus(kind),
    latestChapter: optionalRuleText(source, rules.lastChapter, result, fieldEnv,
      text(detail.latestChapter)),
    wordCount: optionalRuleText(source, rules.wordCount, result, fieldEnv, text(detail.wordCount)),
    mediaType: legadoMediaType(source, detail, result),
