}

// 阅读 BookInfo 对分类、字数、最新章节、简介、封面和目录等可选字段逐项
// 隔离解析异常；某个规则失败不能让整本书详情失败。书名和作者仍按原实现
// 保持严格解析。这里统一承载该语义，避免各端宿主产生不同结果。
function optionalRuleText(source, rule, input, env, fallback) {
  try {
    const value = text(ruleValue(source, rule, input, env, false));
    return value || text(fallback);
  } catch (_) {
    return text(fallback);
  }
}

function optionalRuleUrl(source, rule, input, env, baseUrl, fallback) {
  try {
    // BookInfo URL fields follow AnalyzeRule.getString(..., isUrl = true),
    // including its first-match CSS behavior.  Applying ordinary scalar rules
    // here let a multi-link tocUrl concatenate unrelated href values.
    const raw = text(ruleUrlValue(source, rule, input, env)).trim();
    // AnalyzeRule.getString(..., isUrl = true) delegates to
    // NetworkUtils.getAbsoluteURL(), which deliberately turns javascript:
    // links into an empty value.  Detail pages commonly expose a
    // `javascript:;` expand button next to an already embedded chapter list;
    // treating it as a transport address skips the existing detail body.
    if (/^javascript:/i.test(raw)) return text(fallback);
    const value = urlCompat(raw, baseUrl);
    return value || text(fallback);
  } catch (_) {
    return text(fallback);
  }
}

function parseDetailLoaded(identity, savedValue, source, loaded, input) {
  const saved = Object.assign({}, object(savedValue));
  // Reading evaluates BookInfo fields on one mutable Book instance.  A
  // `java.put()` performed by tocUrl must therefore still be visible when the
  // subsequent catalogue rule calls `java.get()`.  Keep a shared variable bag
  // before creating the field facade below; otherwise a book that did not set a
  // search-stage variable receives a new bag only on the facade and the value
  // is lost when the detail snapshot is persisted.
  saved.__legadoVariables = object(saved.__legadoVariables);
  const rules = sourceRuleTemplate(source).bookInfo;
  let result = loaded.body;
  const env = { result, src: loaded.body, baseUrl: loaded.url, book: saved,
    __legadoExecutionState: input && input.__legadoExecutionState };
  if (rules.init) {
    const initialized = ruleList(source, rules.init, result, env);
    if (initialized.length > 0) result = initialized[0];
  }
  // BookInfo.init is AnalyzeRule.setContent(getElement(init)) in Reading.
  // Subsequent detail rules therefore observe the initialized element through
  // both `result` and `src` (unlike a same-rule pipeline, whose src remains the
  // original response).  Keep that boundary explicit for API detail sources.
  const fieldEnv = Object.assign({}, env, { result, src: result });
  const parsedTitle = text(ruleValue(source, rules.name, result, fieldEnv, false));
  const parsedAuthor = text(ruleValue(source, rules.author, result, fieldEnv, false));
  const parsedKind = optionalRuleText(source, rules.kind, result, fieldEnv, text(saved.kind));
  // BookInfo fields become the current Book before URL templates are expanded.
  // In particular, Reading rules may derive tocUrl from `{{book.kind}}` where
  // kind is supplied by the detail API rather than the search list.
  fieldEnv.book = Object.assign({}, saved, {
    name: parsedTitle || text(saved.title),
    title: parsedTitle || text(saved.title),
    author: parsedAuthor || text(saved.author),
    kind: parsedKind
  });
  const allowRename = (!input || input.canReName !== false) && hasRuleValue(rules.canReName);
  const detail = Object.assign({}, saved, {
    raw: result,
    infoHtml: text(loaded.body),
    title: parsedTitle && (allowRename || !text(saved.title)) ? parsedTitle : text(saved.title),
    author: parsedAuthor && (allowRename || !text(saved.author)) ? parsedAuthor : text(saved.author),
    kind: parsedKind,
    intro: optionalRuleText(source, rules.intro, result, fieldEnv, text(saved.intro)),
    coverUrl: optionalRuleUrl(source, rules.coverUrl, result, fieldEnv, loaded.url,
      text(saved.coverUrl)),
    tocSourceUrl: Number(source.bookSourceType || 0) === 3 ? text(saved.tocSourceUrl) :
      optionalRuleUrl(source, rules.tocUrl, result, fieldEnv, loaded.url,
        text(saved.tocSourceUrl)),
    downloadUrls: [],
    canReName: allowRename
