    let downloadUrls = [];
    try {
      const parsed = ruleValue(source, rules.downloadUrls, result, fieldEnv, true);
      downloadUrls = Array.isArray(parsed) ? parsed : [parsed];
    } catch (_) {}
    detail.downloadUrls = downloadUrls.map(item => urlCompat(item, loaded.url)).filter(Boolean);
  }
  if (!detail.tocSourceUrl && (Number(source.bookSourceType || 0) !== 3 ||
