  // non-empty request values over an older per-book snapshot so a previously
  // cached category-page fallback cannot poison a later detail/catalog open.
  ['sourceKey', 'sourceName', 'bookUrl', 'title', 'author', 'kind', 'coverUrl', 'latestChapter',
    'mediaType']
    .forEach(key => {
      const value = text(input && input[key]);
      if (value) saved[key] = value;
