    'isVolume', 'isLocked', 'nextChapterUrl', '__legadoVariables', 'mediaType']
    .forEach(key => {
      if (value[key] !== undefined) locator[key] = value[key];
    });
  return locator;
}

function publicChapter(chapter) {
  return { chapterKey: text(chapter.chapterKey), title: text(chapter.title),
    ordinal: Number(chapter.index || 0), chapterUrl: text(chapter.chapterKey),
    locator: portableChapterLocator(chapter),
    isVolume: chapter.isVolume === true, isLocked: chapter.isLocked === true,
    mediaType: text(chapter.mediaType) };
}

function legacyCachedCatalog(identity, fingerprint) {
  const cache = stored(catalogCacheKey(identity));
  if (cache.version !== CATALOG_CACHE_VERSION || text(cache.fingerprint) !== fingerprint ||
      cache.storage !== 'preferences-v1' ||
      !Array.isArray(cache.chunkKeys) || Number(cache.chapterCount) < 1) return null;
  const chapters = [];
  for (const key of cache.chunkKeys) {
    const chunk = storageGet(text(key));
    if (!Array.isArray(chunk)) return null;
    for (const chapter of chunk) chapters.push(object(chapter));
  }
  if (chapters.length !== Number(cache.chapterCount)) return null;
  return chapters.map(publicChapter);
