  for (const chapter of chapters) {
    const encoded = JSON.stringify(chapter);
    const itemBytes = utf8ByteLength(encoded) + 1;
    if (chunk.length > 0 && chunkBytes + itemBytes > CATALOG_CHUNK_MAXIMUM_BYTES) {
      chunks.push(chunk);
      chunk = [];
      chunkBytes = 2;
