    ...(Array.isArray(previous.chunkKeys) ? previous.chunkKeys : []),
    ...(Array.isArray(previous.obsoleteChunkKeys) ? previous.obsoleteChunkKeys : [])
  ].map(key => text(key)).filter(Boolean))];
