function portableChapterInput(input, chapterIdentity) {
  const request = object(input);
  const chapter = Object.assign({}, object(request.chapter));
  if (!text(chapter.chapterKey)) chapter.chapterKey = text(chapterIdentity);
  if (!text(chapter.bookKey)) chapter.bookKey = text(request.bookKey);
  if (!text(chapter.sourceKey)) chapter.sourceKey = text(request.sourceKey);
  if (!text(chapter.chapterUrl)) chapter.chapterUrl = text(request.chapterUrl);
