function portableBookInput(input, bookIdentity) {
  const request = object(input);
  const book = Object.assign({}, object(request.book));
  if (!text(book.bookKey)) book.bookKey = text(bookIdentity || request.bookKey);
  if (!text(book.sourceKey)) book.sourceKey = text(request.sourceKey);
