  const snapshot = prepareCatalogSnapshot(source, identity, fingerprint, chapters, cacheBookId);
  // A separately-updated plugin can briefly run on an older host. Keep the old
  // bounded-generation layout as a compatibility fallback; new hosts always
  // take the per-book file path below.
  if (!hasCatalogFileHost()) return writeCatalogPreferencesSync(identity, snapshot);
  const transactionId = catalogTransactionId(input, cacheBookId);
  reader.catalogCache.begin({ bookId: cacheBookId, transactionId, generation: snapshot.generation,
    sourceBinding: text(input.sourceKey), fingerprint, chapterCount: chapters.length });
  try {
    snapshot.chunks.forEach((chunk, index) => reader.catalogCache.writeChunk(
      { bookId: cacheBookId, transactionId, index, value: chunk }));
