  const snapshot = prepareCatalogSnapshot(source, identity, fingerprint, chapters, cacheBookId);
  if (!hasCatalogFileHost()) return await writeCatalogPreferencesAsync(identity, snapshot, state);
  const transactionId = catalogTransactionId(input, cacheBookId);
  await Promise.resolve(reader.catalogCache.begin({ bookId: cacheBookId, transactionId,
    generation: snapshot.generation, sourceBinding: text(input.sourceKey), fingerprint,
    chapterCount: chapters.length }));
  try {
    for (let index = 0; index < snapshot.chunks.length; index++) {
      await Promise.resolve(reader.catalogCache.writeChunk({ bookId: cacheBookId,
        transactionId, index, value: snapshot.chunks[index] }));
    }
    await Promise.resolve(reader.catalogCache.commit({ bookId: cacheBookId, transactionId,
      deferActivation: input.cacheDeferActivation === true }));
  } catch (error) {
    try { await Promise.resolve(reader.catalogCache.abort({ bookId: cacheBookId, transactionId })); }
    catch (_) {}
