    "'source_key', source_key, 'source_json', source_json)), " +
    "'truncated', json('false')) FROM (SELECT source_key, source_json FROM legado_sources " +
    'WHERE enabled = 1 AND (source_key IN (' + placeholders + ') OR ' +
    "json_extract(source_json, '$.bookSourceUrl') IN (" + placeholders + ')))';
