  const candidates = new Map();
  for (let offset = 0; sources.size < wanted.size; offset += 500) {
    const result = databaseQuery(
      'SELECT source_key, source_json FROM legado_sources WHERE enabled = 1 ' +
      'ORDER BY import_order ASC LIMIT 500 OFFSET ' + offset, [], 500);
    if (!result || !Array.isArray(result.rows)) return;
    for (const row of result.rows) {
      const source = storeResolvedSourceAliases(sources, wanted, row);
      collectUniqueStableAliases(candidates, wanted, sources, row, source);
    }
    if (result.rows.length < 500) break;
  }
  applyUniqueStableAliases(sources, candidates);
