async function storeDatabaseDeclaredSourceAliasesAsync(sources, wanted) {
  const candidates = new Map();
  for (let offset = 0; sources.size < wanted.size; offset += 500) {
    const result = await databaseQueryAsync(
      'SELECT source_key, source_json FROM legado_sources WHERE enabled = 1 ' +
