function sourcesByKeys(keys) {
  const wanted = new Set((Array.isArray(keys) ? keys : []).map(value => text(value).trim()).filter(Boolean));
  const sources = new Map();
  if (wanted.size > 0) {
    const sourceKeys = [...wanted];
    for (let offset = 0; offset < sourceKeys.length; offset += 64) {
      const chunk = sourceKeys.slice(offset, offset + 64);
      const result = sourceRowsByKeys(chunk);
      if (!result || !Array.isArray(result.rows)) continue;
      for (const row of result.rows) storeResolvedSourceAliases(sources, wanted, row);
    }
    if (sources.size < wanted.size) storeDatabaseDeclaredSourceAliases(sources, wanted);
  }
  if (sources.size < wanted.size) {
    for (const source of importedSources()) {
      const sourceKey = sourceRecordKey(source);
      if (wanted.has(sourceKey) && !sources.has(sourceKey)) sources.set(sourceKey, object(source));
