    .map(value => text(value).trim()).filter(Boolean));
  const sources = new Map();
  if (wanted.size > 0) {
    const sourceKeys = [...wanted];
    for (let offset = 0; offset < sourceKeys.length; offset += 64) {
      const chunk = sourceKeys.slice(offset, offset + 64);
      const result = await sourceRowsByKeysAsync(chunk);
      if (!result || !Array.isArray(result.rows)) continue;
      for (const row of result.rows) storeResolvedSourceAliases(sources, wanted, row);
