  return values;
}

function sourceRuleStorageKeys(source) {
  const keys = new Set();
  const addValue = value => {
    const key = text(value).trim();
    if (key && !/^https?:\/\//i.test(key)) keys.add(sourceStorageKey(source, 'value.' + key));
  };
  const addCache = (prefix, value) => {
    const key = text(value).trim();
    if (key) keys.add(sourceStorageKey(source, prefix + key));
