  for (const rule of sourceRuleStrings(source)) {
    let match;
    const valuePattern = /\b(?:java|source)\s*\.\s*get\s*\(\s*(["'])([^"']+)\1/gi;
    while ((match = valuePattern.exec(rule)) !== null) addValue(match[2]);
