    return target ? [target] : [];
  }
  const exploreMode = mode === 'explore';
  const capability = exploreMode ? 'exploreUrl' : 'searchUrl';
  const requestedSourceKey = text(input && input.sourceKey).trim();
  if (requestedSourceKey) {
    if (exploreMode) {
      const rssTarget = await databaseRssTargetAsync(requestedSourceKey);
      if (rssTarget) return [rssTarget];
    }
    const databaseTarget = await databaseSourceTargetAsync(requestedSourceKey, capability);
    if (databaseTarget) return [databaseTarget];
    const legacySource = (await importedSourcesAsync()).find(source =>
      source && source.enabled !== false &&
      text(source.bookSourceUrl || source.bookSourceName).trim() === requestedSourceKey &&
      text(source[capability]).trim());
    if (!legacySource) return [];
    return [{
      sourceKey: sourceRecordKey(legacySource),
      name: text(legacySource.bookSourceName || legacySource.bookSourceUrl),
      groups: sourceGroups(legacySource), mediaType: legadoMediaType(legacySource)
