  const legacyTargets = (await importedSourcesAsync())
    .filter(source => source && source.enabled !== false && text(source[capability]).trim())
    .map(source => ({
      sourceKey: sourceRecordKey(source),
      name: text(source.bookSourceName || source.bookSourceUrl),
      groups: sourceGroups(source), mediaType: legadoMediaType(source)
    }));
  if (legacyTargets.length > 0) return legacyTargets;
  const active = object(reader.storage.get(ACTIVE_SOURCE_RECORD_KEY));
  if (active.enabled === false || !text(active[capability]).trim()) return [];
