  const pattern = text(source.bookUrlPattern).trim();
  if (pattern && pattern !== 'NONE') {
    // Reading uses Kotlin String.matches(), which requires the *entire*
    // response URL to match bookUrlPattern. JavaScript RegExp#test only needs
    // a substring match: a broad pattern such as `https://site/.*/` would
    // otherwise mistake a redirected search list (`.../result/?id=...`) for a
    // detail page. Keep this check anchored just like Reading.
    let isDetailUrl = false;
