  const sourceName = text(source && (source.bookSourceName || source.bookSourceUrl)).trim();
  if (!source || !sourceName) return { valid: false, count: 0, message: '书源不存在或已被删除' };
  if (!text(source.searchUrl).trim()) return { valid: false, count: 0, message: '未配置搜索地址' };
  const rules = sourceRuleTemplate(source).search;
  if (!hasRuleValue(rules.bookList)) return { valid: false, count: 0, message: '未配置搜索列表规则' };
  let state = null;
  try {
    const keyword = text(input && input.keyword).trim() || '我的';
    state = await prepareExecutionState([source], input || {});
    const books = searchSource(source, { keyword, page: 1, __legadoExecutionState: state });
    const count = Array.isArray(books) ? books.length : 0;
    return { valid: true, count,
      message: count > 0 ? `搜索成功，返回 ${count} 本` : '请求成功，但返回 0 本（视为有效）' };
  } catch (error) {
