function stripExploreJavascriptComments(value) {
  const raw = text(value);
  let output = '';
  let quote = '';
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote) {
      output += character;
      if (escaped) { escaped = false; continue; }
      if (character === '\\') { escaped = true; continue; }
      if (character === quote) quote = '';
      continue;
    }
    if (character === '"' || character === "'" || character === '`') {
      quote = character;
      output += character;
      continue;
    }
    if (character === '/' && raw[index + 1] === '/') {
      index += 2;
      while (index < raw.length && raw[index] !== '\n' && raw[index] !== '\r') index++;
      if (index < raw.length) output += raw[index];
      continue;
    }
    if (character === '/' && raw[index + 1] === '*') {
      index += 2;
      while (index < raw.length && !(raw[index] === '*' && raw[index + 1] === '/')) {
        if (raw[index] === '\n' || raw[index] === '\r') output += raw[index];
        index++;
      }
      if (index < raw.length) index++;
      continue;
    }
    output += character;
  }
  return output;
