  if (!raw.startsWith('[')) return [];
  let normalized = '';
  const contexts = [];
  let quote = '';
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote) {
      if (escaped) { normalized += character; escaped = false; continue; }
      if (character === '\\') { normalized += character; escaped = true; continue; }
      if (character === quote) {
        normalized += character;
        quote = '';
        continue;
      }
      // Gson's lenient reader, used by Reading for discover-kind arrays,
      // accepts decoded control characters inside quoted values. Source JSON
      // decoding turns exported `\\n`/`\\t` escapes (and occasionally a NUL
      // used only for title decoration) back into those characters before this
      // second parse. Re-escape them for the strict JSON parser without
      // changing any executable URL rule text.
      if (character === '\n') { normalized += '\\n'; continue; }
      if (character === '\r') { normalized += '\\r'; continue; }
      if (character === '\t') { normalized += '\\t'; continue; }
      if (character.charCodeAt(0) < 0x20) {
        normalized += '\\u' + character.charCodeAt(0).toString(16).padStart(4, '0');
        continue;
      }
