      continue;
    }
    const valueContext = contexts.length > 0 ? contexts[contexts.length - 1] : null;
    if (valueContext && valueContext.object && valueContext.expectsValue && !/\s/.test(character)) {
      if (character === '"' || character === "'" || character === '`' ||
          character === '{' || character === '[') {
