    if (character === '"' || character === "'" || character === '`') {
      quote = character;
      normalized += character;
      continue;
    }
    if (character === '{') {
      contexts.push({ object: true, expectsKey: true, expectsValue: false });
      normalized += character;
      continue;
    }
    if (character === '}') {
      contexts.pop();
      normalized += character;
      continue;
    }
    if (character === '[') {
      contexts.push({ object: false, expectsKey: false, expectsValue: false });
      normalized += character;
      continue;
    }
    if (character === ']') {
      contexts.pop();
