  const dynamicPageUrl = /\{\{[\s\S]*\bpage\b|<js>[\s\S]*\bpage\b|@js:[\s\S]*\bpage\b/i
    .test(text((rssMenuEntries(source).find((item, index) =>
      rssMenuKey(item, index) === text(input && input.category)) || {}).url || source.sourceUrl));
  const pages = dynamicPageUrl || !text(source.ruleNextPage).trim() ? 1 : requestedPage;
  const visited = new Set();
  for (let page = 1; page <= pages && target && !visited.has(target); page++) {
    visited.add(target);
    const env = Object.assign({}, selected.env, { page, baseUrl: target,
      __legadoExecutionState: state });
    loaded = await loadByUrlAsync(source, target, env, rssWebOptions(source));
    if (page >= pages) break;
    const next = ruleList(source, source.ruleNextPage, loaded.body,
      Object.assign({}, env, { result: loaded.body, src: loaded.body, baseUrl: loaded.url }))
      .map(value => urlCompat(value, loaded.url)).find(value => value && !visited.has(value));
    target = text(next);
  }
  return { loaded, env: selected.env };
}

function rssArticleSummary(source, raw, env, loaded, index) {
