async function detailAsync(input) {
  const identity = text(input.bookKey || input.bookUrl);
  const execution = await sourceAndExecutionState(input, [identity, detailCacheKey(identity)]);
  const source = execution.source;
  const state = execution.state;
  try {
    let saved = detailSeed(identity, input);
    if (isRssSource(source) || saved.__fishreaderRssArticle === true) {
      return rssDetailResult(identity, saved, source, input);
    }
    if (!saved.bookUrl) throw new Error('书籍标识已失效，请重新搜索');
    const rules = sourceRuleTemplate(source).bookInfo;
    const fingerprint = detailFingerprint(source, saved, rules);
    const cache = stored(detailCacheKey(identity));
    if (input.forceRefresh !== true && text(cache.fingerprint) === fingerprint &&
        cache.detail && cache.result) {
      const restored = Object.assign({}, saved, object(cache.detail));
      // A cached detail may have been produced before the source was imported
      // with its final BookSourceType (most visibly for type=2 comic sources).
      // Re-evaluate the normalized type from the current source and the current
      // search snapshot instead of letting the stale cached `text` value select
      // FishReader's text reader.
      restored.mediaType = legadoMediaType(source, restored, restored.raw);
      const cachedResult = Object.assign({}, object(cache.result), {
        mediaType: restored.mediaType
      });
      storageSet(identity, restored);
      return cachedResult;
    }
    const loaded = text(saved.infoHtml) ? { body: text(saved.infoHtml), url: saved.bookUrl } :
      await loadByUrlAsync(source, saved.bookUrl, { result: saved.raw, book: saved,
        baseUrl: saved.bookUrl, __legadoExecutionState: state });
    const parsed = parseDetailLoaded(identity, saved, source, loaded,
      Object.assign({}, input || {}, { __legadoExecutionState: state }));
    const detail = parsed.detail;
    const output = detailResult(identity, detail, source, parsed.rules, parsed.result, parsed.fieldEnv);
    const cachedDetail = Object.assign({}, detail);
    storageSet(identity, detail);
    storageSet(detailCacheKey(identity),
      { fingerprint, updatedAtMs: Date.now(), detail: cachedDetail, result: output });
    return output;
  } finally {
    await finishExecutionState(state);
  }
}

function detailSync(input) {
