async function catalogAsync(input) {
  const identity = text(input.bookKey || input.tocUrl || input.bookUrl);
  const cacheKey = catalogCacheKey(identity);
  const execution = await sourceAndExecutionState(input, [identity, cacheKey]);
  const source = execution.source;
  const executionState = execution.state;
  try {
    let saved = stored(identity);
    if (isRssSource(source) || object(saved).__fishreaderRssArticle === true ||
        /^legado\.rss\.article\./.test(identity)) {
      return rssCatalog(identity, saved, source, input);
    }
    // Detail and catalog are separate host executions.  Normally the detail
    // snapshot is already persisted, but a discovery result can be opened in a
    // fresh worker (or after a stale snapshot was cleared).  Rehydrate it from
    // the concrete URL carried by the request instead of failing with an empty
    // catalog.  This keeps the fallback generic for every Reading 3 source.
    if (!saved.tocSourceUrl && text(input.bookUrl)) {
      await detailAsync({
        bookKey: identity,
        sourceKey: text(input.sourceKey),
        bookUrl: text(input.bookUrl),
        mediaType: text(input.mediaType),
        forceRefresh: false
      });
      // detailAsync owns and clears its nested execution state when it settles;
      // resume catalog reads/writes against the outer state.
      activeExecutionState = executionState;
      saved = object(await reloadStorageValue(executionState, identity));
    }
    if (!saved.tocSourceUrl) throw new Error('目录地址已失效，请重新打开详情');
    const rules = sourceRuleTemplate(source).toc;
    let fingerprint = ruleFingerprint([LEGADO_ENGINE_REVISION, source.bookSourceType, saved.tocSourceUrl, rules,
      text(source.jsLib)]);
    if (input.forceRefresh !== true) {
      const cached = await cachedFileCatalogAsync(input, identity, fingerprint);
      if (cached !== null) {
        const cachedMediaType = legadoMediaType(source, saved, saved.raw);
        cached.forEach(chapter => { if (!text(chapter.mediaType)) chapter.mediaType = cachedMediaType; });
        return cached;
      }
    }
    if (rules.preUpdateJs) {
      const flags = {};
      evaluateJs(source, rules.preUpdateJs,
        { result: saved.raw, book: saved, baseUrl: saved.tocSourceUrl,
          __legadoFlags: flags, __legadoExecutionState: executionState });
      if (flags.refreshTocUrl || flags.reGetBook) {
        await detailAsync({ bookKey: identity, sourceKey: saved.sourceKey, forceRefresh: true });
        activeExecutionState = executionState;
        saved = object(await reloadStorageValue(executionState, identity));
        fingerprint = ruleFingerprint([LEGADO_ENGINE_REVISION, source.bookSourceType, saved.tocSourceUrl, rules,
          text(source.jsLib)]);
      }
    }
    const pages = [];
    const visited = new Set();
    let chapterListRule = text(rules.chapterList).trim();
    const reverseChapterList = chapterListRule.startsWith('-') && chapterListRule.length > 1;
    if ((reverseChapterList || chapterListRule.startsWith('+')) && chapterListRule.length > 1) {
      chapterListRule = chapterListRule.slice(1).trim();
    }
    let pageUrl = saved.tocSourceUrl;
    for (let page = 1; pageUrl && !visited.has(pageUrl); page++) {
      visited.add(pageUrl);
      const loaded = await loadByUrlAsync(source, pageUrl,
        { result: saved.raw, book: saved, page, baseUrl: pageUrl,
          __legadoExecutionState: executionState });
      const env = { result: loaded.body, src: loaded.body, book: saved, page,
        baseUrl: loaded.url, __legadoExecutionState: executionState };
      const selected = catalogRuleItems(source, chapterListRule, loaded.body, env);
      for (const raw of selected.items) pages.push({ raw, baseUrl: loaded.url, env: selected.env });
      if (!rules.nextTocUrl) break;
      const nextUrls = ruleList(source, rules.nextTocUrl, loaded.body, env)
        .map(value => urlCompat(value, loaded.url)).filter(value => value && !visited.has(value));
      if (nextUrls.length === 0) break;
      if (nextUrls.length === 1) {
        pageUrl = nextUrls[0];
        continue;
      }
      const parallelUrls = nextUrls;
      parallelUrls.forEach(value => visited.add(value));
      const parallelPages = await Promise.all(parallelUrls.map((value, index) =>
        loadByUrlAsync(source, value, { result: saved.raw, book: saved, page: page + index + 1,
          baseUrl: value, __legadoExecutionState: executionState })));
      parallelPages.forEach((parallel, index) => {
        const parallelEnv = { result: parallel.body, src: parallel.body, book: saved,
          page: page + index + 1, baseUrl: parallel.url,
          __legadoExecutionState: executionState };
        const selected = catalogRuleItems(source, chapterListRule, parallel.body, parallelEnv);
        selected.items.forEach(raw =>
          pages.push({ raw, baseUrl: parallel.url, env: selected.env }));
      });
      break;
    }
    const chapterPages = pages;
    const batchValues = await batchHtmlRuleValuesAsync(source, chapterPages, {
      chapterUrl: rules.chapterUrl, chapterName: rules.chapterName,
      updateTime: rules.updateTime, isVolume: rules.isVolume,
      isLocked: rules.isVip || rules.isPay
    });
    let chapters = chapterPages.map((pageItem, index) => {
    const raw = pageItem.raw;
    const rowEnv = Object.assign({}, pageItem.env,
      { result: raw, src: raw, chapter: object(raw), index: index + 1, gInt: index + 1 });
    const prepared = batchValues ? batchValues[index] : {};
    const field = (key, rule) => {
      if (Object.prototype.hasOwnProperty.call(prepared, key)) return prepared[key];
      const direct = directCatalogJsonRuleValue(rule, raw);
      return direct.matched ? direct.value : ruleValue(source, rule, raw, rowEnv, false);
    };
    const title = text(field('chapterName', rules.chapterName)).trim();
    if (!title) return null;
    // Reading creates a BookChapter, assigns its parsed title, then evaluates
    // chapterUrl. Source rules are consequently allowed to refer to
    // `{{chapter.title}}` in the URL rule even when the raw JSON row uses a
    // different key (for example `chapter_name`). Preserve that order here.
    rowEnv.chapter = Object.assign({}, object(raw), { title });
    const volumeRule = text(rules.isVolume).trim();
    const volumeRaw = volumeRule ? directJsonRuleValue(rules.isVolume, raw) : { matched: false };
    // AnalyzeRule does not evaluate an absent optional catalogue rule against
    // the current Element. An empty isVolume/isVip rule therefore means false,
    // rather than the truthiness of the chapter row's outerHTML.
    const isVolume = volumeRule ? legadoBoolean(volumeRaw.matched ? volumeRaw.value :
      field('isVolume', rules.isVolume)) : false;
    const chapterUrlValue = field('chapterUrl', rules.chapterUrl);
    const rawChapterUrl = text(chapterUrlValue).trim();
    // Reading uses a synthetic title+index identity for volume rows and the
    // current catalog page for ordinary rows whose URL rule is empty.
    const chapterUrl = rawChapterUrl ? chapterUrlCompat(chapterUrlValue, raw, pageItem.baseUrl) :
      (isVolume ? title + String(index) : pageItem.baseUrl);
    const updateTime = text(rules.updateTime).trim() ?
      text(field('updateTime', rules.updateTime)) : '';
    const chapterVariables = object(rowEnv.chapter.__legadoVariables);
    const chapter = { chapterKey: '', bookKey: identity, sourceKey: text(saved.sourceKey), chapterUrl,
      __legadoRawChapterUrl: rawChapterUrl || (isVolume ? title + String(index) : pageItem.baseUrl), raw, index,
      title, updateTime, tag: updateTime, isVolume,
      // Reading keeps variables written by a catalogue field rule on the
      // BookChapter entity.  They must survive the row-to-chapter conversion
      // because content rules commonly read them through java.get().
      ...(Object.keys(chapterVariables).length > 0 ? { __legadoVariables: chapterVariables } : {}),
      isLocked: (() => {
        const lockRule = text(rules.isVip || rules.isPay).trim();
        if (!lockRule) return false;
        const lockRaw = directJsonRuleValue(lockRule, raw);
        return legadoBoolean(lockRaw.matched ? lockRaw.value : field('isLocked', lockRule));
      })() };
    return chapter;
    }).filter(Boolean);
    // BookChapterList applies the source-order transform before LinkedHashSet
    // de-duplication.  The order is observable when duplicate URLs carry
    // different titles, because Reading keeps the first row in that transformed
    // order rather than the first row in the raw response.
    if (!reverseChapterList) chapters.reverse();
    const seenChapters = new Set();
    chapters = chapters.filter(chapter => {
      // Reading de-duplicates BookChapter before AnalyzeUrl resolves a relative
      // chapter URL against its catalogue page.  Keep that ordering observable:
      // identical fragments/relative links repeated on paginated catalogues are
      // one chapter even though their later absolute URLs have different bases.
      const key = text(chapter.__legadoRawChapterUrl || chapter.chapterUrl);
      if (seenChapters.has(key)) return false;
      seenChapters.add(key);
      return true;
    });
    if (saved.reverseToc !== true) chapters.reverse();
    chapters.forEach(chapter => { delete chapter.__legadoRawChapterUrl; });
    const catalogMediaType = legadoMediaType(source, saved, saved.raw);
    saved.mediaType = catalogMediaType;
    chapters.forEach(chapter => { chapter.mediaType = catalogMediaType; });
    for (let index = 0; index < chapters.length; index++) {
      chapters[index].index = index;
      if (rules.formatJs) {
        const formatted = evaluateJs(source, rules.formatJs,
          { result: chapters[index].raw, book: saved, chapter: chapters[index],
            title: chapters[index].title, index: index + 1, gInt: index + 1,
            baseUrl: chapters[index].chapterUrl });
        if (formatted !== undefined && formatted !== null && text(formatted)) {
          chapters[index].title = text(formatted);
        }
      }
      chapters[index].nextChapterUrl = index + 1 < chapters.length ?
        text(chapters[index + 1].chapterUrl) : '';
    }
    storageSet(identity, saved);
    return await writeCatalogFileAsync(input, source, identity, fingerprint, chapters, executionState);
  } finally {
    await finishExecutionState(executionState);
  }
}

function catalogSync(input) {
  activeExecutionState = { storageValues: {}, cookieValues: {}, pendingWrites: [] };
  try {
  const identity = text(input.bookKey || input.tocUrl || input.bookUrl);
  const source = sourceForInput(input);
  let saved = stored(identity);
  if (isRssSource(source) || object(saved).__fishreaderRssArticle === true ||
      /^legado\.rss\.article\./.test(identity)) {
