  let pageUrl = saved.chapterUrl, finalBaseUrl = saved.chapterUrl;
  let finalRawResult = '', finalRuleEnv = null, initialRawResult = '', initialRuleEnv = null;
  let responseMedia = null;
  for (let page = 1; pageUrl && !visited.has(pageUrl); page++) {
    visited.add(pageUrl);
    const loaded = loadByUrl(source, pageUrl, { result: saved.raw, book, chapter: saved,
      title: saved.title, page, nextChapterUrl: saved.nextChapterUrl, baseUrl: pageUrl },
    { webJs: rules.webJs, sourceRegex: rules.sourceRegex });
    // Match Reading's AnalyzeRule contract: baseUrl is the original chapter
    // URL; the percent-encoded/redirected transport URL is redirectUrl only.
    finalBaseUrl = pageUrl;
    const ruleBody = loaded.body;
    responseMedia = responseMedia || responseMediaContent(loaded, mediaType, pageUrl);
    const env = { result: ruleBody, src: ruleBody, book, chapter: saved, page,
      nextChapterUrl: saved.nextChapterUrl, title: saved.title, baseUrl: pageUrl };
    finalRawResult = ruleBody;
    finalRuleEnv = env;
    if (!initialRuleEnv) {
      initialRawResult = ruleBody;
      initialRuleEnv = env;
    }
    const pageContent = text(rules.content).trim() ?
      text(ruleValue(source, rules.content, ruleBody, env, false)) : text(saved.chapterUrl);
    contents.push(mediaType === 'audiobook' || Number(source.bookSourceType) === 1 ||
      Number(source.bookSourceType) === 4 ?
      pageContent : formatLegadoHtml(pageContent, loaded.url));
    if (!rules.nextContentUrl) break;
    const nextUrls = ruleList(source, rules.nextContentUrl, loaded.body, env)
      .map(value => urlCompat(value, loaded.url))
      .filter(value => value && !visited.has(value) && value !== saved.nextChapterUrl);
    if (nextUrls.length === 0) break;
    if (nextUrls.length === 1) {
      pageUrl = nextUrls[0];
      continue;
    }
    const parallelUrls = nextUrls;
    parallelUrls.forEach(value => visited.add(value));
    parallelUrls.forEach((value, index) => {
      const parallel = loadByUrl(source, value, { result: saved.raw, book, chapter: saved,
        title: saved.title, page: page + index + 1, nextChapterUrl: saved.nextChapterUrl,
        baseUrl: value }, { webJs: rules.webJs, sourceRegex: rules.sourceRegex });
      const parallelBody = parallel.body;
      responseMedia = responseMedia || responseMediaContent(parallel, mediaType, value);
      const parallelEnv = { result: parallelBody, src: parallelBody, book, chapter: saved,
        page: page + index + 1, nextChapterUrl: saved.nextChapterUrl,
        title: saved.title, baseUrl: value };
      const parallelContent = text(rules.content).trim() ?
        text(ruleValue(source, rules.content, parallelBody, parallelEnv, false)) : '';
      contents.push(mediaType === 'audiobook' || Number(source.bookSourceType) === 1 ||
        Number(source.bookSourceType) === 4 ?
        parallelContent : formatLegadoHtml(parallelContent, parallel.url));
      finalBaseUrl = value;
      finalRawResult = parallelBody;
      finalRuleEnv = parallelEnv;
    });
    break;
  }
  let content = contents.filter(Boolean).join('\n');
  const sourceType = Number(source.bookSourceType || 0);
  const subContent = text(rules.subContent).trim() && initialRuleEnv ?
    text(ruleValue(source, rules.subContent, initialRawResult, initialRuleEnv, false)) : '';
  if (sourceType === 0 && subContent) content = [content, subContent].filter(Boolean).join('\n');
  if (rules.replaceRegex) content = applyContentReplacement(source, rules.replaceRegex, content,
    Object.assign({}, finalRuleEnv || {}, { result: content, src: content,
      baseUrl: finalBaseUrl }));
  const title = text(rules.title).trim() ? text(ruleValue(source, rules.title, finalRawResult,
    Object.assign({}, finalRuleEnv || {}, { result: finalRawResult, src: finalRawResult,
      book, chapter: saved, title: saved.title, baseUrl: finalBaseUrl }), false)) : text(saved.title);
  if (!content && sourceType === 0 && mediaType === 'text') throw new Error('内容为空');
  const structured = structuredChapterFromCandidates(
    [content, finalRawResult, saved.raw, book.raw, saved],
    mediaType,
    finalBaseUrl,
    defaultMediaHeaders
  );
  const explicitRuleMedia = explicitRuleMediaContent(content, mediaType, finalBaseUrl,
    defaultMediaHeaders);
  const executionMedia = executionMediaContent(activeExecutionState, defaultMediaHeaders);
  const subMetadata = sourceType === 1 && subContent ? { lyric: subContent } :
    (sourceType === 4 && subContent ? { danmaku: subContent } : {});
  if (explicitRuleMedia) return Object.assign(explicitRuleMedia, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  if (responseMedia && Number(responseMedia.__legadoMediaConfidence || 0) >= 2) return Object.assign(responseMedia, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  if (executionMedia && Number(executionMedia.__legadoMediaConfidence || 0) >= 2) return Object.assign(executionMedia, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  if (structured && structured.contentType === 'audio' &&
      Array.isArray(structured.mediaUrls) && structured.mediaUrls.length > 0) {
    return Object.assign(structured, subMetadata,
      { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  }
  if (responseMedia) return Object.assign(responseMedia, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  if (executionMedia) return Object.assign(executionMedia, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  if (structured) return Object.assign(structured, subMetadata,
    { baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle) });
  return Object.assign({ content, contentType: 'text', baseUrl: finalBaseUrl,
    title, imageStyle: text(rules.imageStyle) }, subMetadata);
}

module.exports.content = input => globalThis.__fishreaderHostSynchronous === false ?
  contentAsync(input) : contentSync(input);

async function readingActionContext(input) {
  const request = object(input);
  const chapterIdentity = text(request.chapterKey || request.chapterUrl);
  const storageKeys = chapterIdentity ? [chapterIdentity] : [];
  const catalogChunk = await catalogChunkForInput(request, chapterIdentity);
  request.__legadoCatalogChunk = catalogChunk;
  const execution = await sourceAndExecutionState(request, storageKeys);
  let chapter = object(request.chapter);
  if (Object.keys(chapter).length === 0 && chapterIdentity) {
    chapter = stored(chapterIdentity);
    if (!chapter.chapterUrl) chapter = snapshotChapter(chapterIdentity, request.cacheBookId, catalogChunk);
  }
  const bookIdentity = text(request.bookKey || chapter.bookKey || request.bookUrl);
  if (bookIdentity) await preloadStorageKeys(execution.state,
    [bookIdentity, detailCacheKey(bookIdentity)]);
  const book = Object.assign({}, bookIdentity ? stored(bookIdentity) : {},
    bookIdentity ? object(stored(detailCacheKey(bookIdentity)).detail) : {}, object(request.book));
  return { source: execution.source, state: execution.state, book, chapter };
}

function actionResult(value, effects) {
  const raw = text(value);
  return { handled: /^(true|1)$/i.test(raw), value: raw,
    openUrl: /^https?:\/\//i.test(raw) ? raw : '',
    messages: effects.messages, uiEffects: effects.uiEffects,
    browser: effects.browser || null };
}

module.exports.payAction = async input => {
  const request = object(input);
  const context = await readingActionContext(request);
  try {
    const rule = sourceRuleTemplate(context.source).content.payAction;
    if (!text(rule).trim()) throw new Error('该源未配置购买操作');
    const effects = { messages: [], uiEffects: [], browser: null };
    const chapterUrl = text(context.chapter.chapterUrl || request.chapterUrl);
    const value = evaluateJs(context.source, rule, {
      result: null, src: null, book: context.book, chapter: context.chapter,
      title: text(context.chapter.title || input.title), baseUrl: chapterUrl,
      __legadoExecutionState: context.state, __legadoRuntimeEffects: effects
    });
    return actionResult(value, effects);
  } finally {
    await finishExecutionState(context.state);
  }
};

module.exports.callback = async input => {
  const request = object(input);
  const context = await readingActionContext(request);
  try {
    const rule = sourceRuleTemplate(context.source).content.callBackJs;
    if (context.source.eventListener !== true || !text(rule).trim()) {
      return { handled: false, value: '', openUrl: '', messages: [], uiEffects: [], browser: null };
    }
    const effects = { messages: [], uiEffects: [], browser: null };
    const value = evaluateJs(context.source, rule, {
      event: text(request.event), result: request.result === undefined ? null : request.result,
      book: context.book, chapter: context.chapter,
      title: text(context.chapter.title || request.title),
      baseUrl: text(context.chapter.chapterUrl || request.chapterUrl || request.bookUrl ||
        sourceNetworkUrl(context.source)), __legadoExecutionState: context.state,
      __legadoRuntimeEffects: effects
    });
    return actionResult(value, effects);
  } finally {
    await finishExecutionState(context.state);
  }
};

module.exports.image = async input => {
  const requestInput = object(input);
  const bookKey = text(requestInput.bookKey || requestInput.bookUrl);
  const execution = await sourceAndExecutionState(requestInput, bookKey ? [bookKey] : []);
  try {
    const source = execution.source;
    const url = text(requestInput.url || requestInput.src).trim();
    if (!url) throw new Error('图片地址为空');
    const env = { result: null, src: url, baseUrl: url,
      book: object(requestInput.book || (bookKey ? stored(bookKey) : {})) };
    const request = parseAjaxRequest(url, source, env);
    request.method = request.method || 'GET';
    request.headers = mergeRequestHeaders(sourceHeaders(source, env), request.headers || {});
    request.responseType = 'bytes';
    const response = await Promise.resolve(reader.http.fetch(request));
    if (!response || Number(response.status || 0) < 200 || Number(response.status || 0) >= 400) {
      throw new Error('图片请求失败：HTTP ' + text(response && response.status));
    }
    const original = response.data !== undefined ? byteArrayValue(response.data) :
      byteArrayValue(response.bodyBase64 !== undefined ? response.bodyBase64 : response.body, 'base64');
    const rules = sourceRuleTemplate(source);
    const decodeRule = requestInput.isCover === true ? source.coverDecodeJs : rules.content.imageDecode;
    let decoded = original;
    if (text(decodeRule).trim()) {
      decoded = byteArrayValue(evaluateJs(source, decodeRule, Object.assign({}, env, {
        result: original, src: url, baseUrl: text(response.url) || request.url
      })));
      if (decoded.length === 0 && original.length > 0) throw new Error('图片解密规则未返回有效字节');
    }
    const headers = object(response.headers);
    const contentTypeName = Object.keys(headers).find(name => name.toLowerCase() === 'content-type');
    return { dataBase64: byteArrayToBase64(decoded),
      contentType: text(contentTypeName ? headers[contentTypeName] : '') || 'application/octet-stream' };
  } finally {
    await finishExecutionState(execution.state);
  }
};

module.exports.loginCheck = async input => {
  const source = sourceForInput(input);
  // Comparison probes can replay a body captured from Reading through the same
  // production list mapper.  This keeps network/WebView differences out of a
  // selector-compatibility audit; ordinary hosts never send these private flags.
  if (input && input.__fishreaderProbeDetailParse === true) {
    const body = text(input.body);
    const baseUrl = text(input.baseUrl || input.bookUrl || sourceNetworkUrl(source));
    const identity = text(input.bookKey || input.bookUrl || baseUrl);
    const saved = Object.assign({ bookKey: identity, bookUrl: text(input.bookUrl || baseUrl),
      sourceKey: text(input.sourceKey) }, object(input.book));
    const state = await prepareExecutionState([source], input || {});
    try {
      const parsed = parseDetailLoaded(identity, saved, source, { body, url: baseUrl },
        Object.assign({}, input || {}, { __legadoExecutionState: state }));
      const detail = parsed.detail;
      return { loggedIn: false, message: 'comparison probe', title: text(detail.title || detail.name),
        author: text(detail.author), tocUrl: text(detail.tocSourceUrl || detail.tocUrl),
        introLength: text(detail.intro).length };
    } finally {
      await finishExecutionState(state);
    }
  }
  if (input && input.__fishreaderProbeContentParse === true) {
    const rules = sourceRuleTemplate(source).content;
    const body = text(input.body);
    const baseUrl = text(input.baseUrl || input.chapterUrl || sourceNetworkUrl(source));
    const book = object(input.book);
    const chapter = Object.assign({ title: text(input.chapterTitle), chapterUrl: baseUrl },
      object(input.chapter));
    const state = await prepareExecutionState([source], input || {});
    try {
      const env = { result: body, src: body, book, chapter, page: 1,
        nextChapterUrl: text(input.nextChapterUrl), title: text(chapter.title), baseUrl,
        __legadoExecutionState: state };
      const sourceType = Number(source.bookSourceType || 0);
      const mediaType = chapterExecutionMediaType(source, input, book, chapter);
      state.captureMediaRequests = mediaType === 'audiobook' ? 'audiobook' : '';
      state.mediaRequestCandidates = [];
      const parsed = text(rules.content).trim() ?
        text(ruleValue(source, rules.content, body, env, false)) : text(chapter.chapterUrl);
      let content = mediaType === 'audiobook' || sourceType === 1 || sourceType === 4 ?
        parsed : formatLegadoHtml(parsed, baseUrl);
      const subContent = text(rules.subContent).trim() ?
        text(ruleValue(source, rules.subContent, body, env, false)) : '';
      if (sourceType === 0 && subContent) content = [content, subContent].filter(Boolean).join('\n');
      if (rules.replaceRegex) content = applyContentReplacement(source, rules.replaceRegex, content,
        Object.assign({}, env, { result: content, src: content }));
      const structured = structuredChapterFromCandidates(
        [content, body, chapter.raw, book.raw, chapter], mediaType, baseUrl, {});
      const executionMedia = executionMediaContent(state, {});
      const media = structured || executionMedia;
      const mediaUrls = Array.isArray(media && media.mediaUrls) ? media.mediaUrls :
        (text(media && media.mediaUrl) ? [text(media.mediaUrl)] : []);
      return { loggedIn: false, message: 'comparison probe', contentType:
        text(media && media.contentType) || 'text', contentLength: content.length,
        mediaUrlCount: mediaUrls.length, preview: content.slice(0, 160) };
    } finally {
      await finishExecutionState(state);
    }
  }
  if (input && input.__fishreaderProbeCatalogParse === true) {
    const rules = sourceRuleTemplate(source).toc;
    const body = text(input.body);
    const baseUrl = text(input.baseUrl || sourceNetworkUrl(source));
    const book = Object.assign({ bookUrl: text(input.bookUrl), tocSourceUrl: baseUrl },
      object(input.book));
    const state = await prepareExecutionState([source], input || {});
    try {
      let chapterListRule = text(rules.chapterList).trim();
      const reverseChapterList = chapterListRule.startsWith('-') && chapterListRule.length > 1;
      if ((reverseChapterList || chapterListRule.startsWith('+')) && chapterListRule.length > 1) {
        chapterListRule = chapterListRule.slice(1).trim();
      }
      const env = { result: body, src: body, book, page: 1, baseUrl,
        __legadoExecutionState: state };
      const selected = catalogRuleItems(source, chapterListRule, body, env);
      const pages = selected.items.map(raw => ({ raw, baseUrl, env: selected.env }));
      const preparedRows = await batchHtmlRuleValuesAsync(source, pages, {
        chapterUrl: rules.chapterUrl, chapterName: rules.chapterName,
        updateTime: rules.updateTime, isVolume: rules.isVolume,
        isLocked: rules.isVip || rules.isPay
      });
      let chapters = pages.map((pageItem, index) => {
        const raw = pageItem.raw;
        const rowEnv = Object.assign({}, pageItem.env,
          { result: raw, src: raw, chapter: object(raw), index: index + 1, gInt: index + 1 });
        const prepared = preparedRows ? preparedRows[index] : {};
        const field = (key, rule) => {
          if (Object.prototype.hasOwnProperty.call(prepared, key)) return prepared[key];
          const direct = directCatalogJsonRuleValue(rule, raw);
          return direct.matched ? direct.value : ruleValue(source, rule, raw, rowEnv, false);
        };
        const title = text(field('chapterName', rules.chapterName)).trim();
        if (!title) return null;
        rowEnv.chapter = Object.assign({}, object(raw), { title });
        const volumeRule = text(rules.isVolume).trim();
        const volumeRaw = volumeRule ? directJsonRuleValue(rules.isVolume, raw) : { matched: false };
        const isVolume = volumeRule ? legadoBoolean(volumeRaw.matched ? volumeRaw.value :
          field('isVolume', rules.isVolume)) : false;
        const chapterUrlValue = field('chapterUrl', rules.chapterUrl);
        const rawChapterUrl = text(chapterUrlValue).trim();
        return { title, isVolume, rawChapterUrl: rawChapterUrl ||
          (isVolume ? title + String(index) : baseUrl) };
      }).filter(Boolean);
      if (!reverseChapterList) chapters.reverse();
      const seen = new Set();
      chapters = chapters.filter(chapter => {
        if (seen.has(chapter.rawChapterUrl)) return false;
        seen.add(chapter.rawChapterUrl);
        return true;
      });
      if (book.reverseToc !== true) chapters.reverse();
      return { loggedIn: false, message: 'comparison probe', itemCount: pages.length,
        count: chapters.length, titles: chapters.slice(0, 8).map(chapter => chapter.title) };
    } finally {
      await finishExecutionState(state);
    }
  }
  if (input && (input.__fishreaderProbeSearchResponseParse === true ||
      input.__fishreaderProbeExploreParse === true)) {
    const entrypoint = input.__fishreaderProbeExploreParse === true ? 'explore' : 'search';
    const rules = bookListRulesFor(source, entrypoint);
    const body = text(input.body);
    const baseUrl = text(input.baseUrl || sourceNetworkUrl(source));
    const state = await prepareExecutionState([source], input || {});
    try {
      const env = { key: text(input.keyword || '我的'), page: Number(input.page || 1),
        result: null, src: body, baseUrl, __legadoExecutionState: state };
      const items = ruleList(source, bookListRuleValue(rules.bookList), body, env);
      const books = mapBookListResults(source, rules, items, env,
        { body, url: baseUrl, status: 200, headers: {}, requestHeaders: {} }, false,
        { requireBookUrl: entrypoint === 'explore' });
      return { loggedIn: false, message: 'comparison probe', itemCount: items.length,
        count: books.length, titles: books.slice(0, 8).map(book => text(book.title)) };
    } finally {
      await finishExecutionState(state);
    }
  }
  if (text(source.loginCheckJs).trim()) {
    const value = evaluateJs(source, source.loginCheckJs, { result: input || {},
      baseUrl: sourceNetworkUrl(source) });
    if (value && typeof value === 'object') {
      return { loggedIn: value.loggedIn === true, message: text(value.message) };
    }
    return { loggedIn: value === true || /^(true|1|ok)$/i.test(text(value)), message: text(value) };
  }
  const context = loginContext(source, input || {});
  const cookieUrl = sourceCookieProbeUrl(source);
  const hasCookie = cookieUrl ? text(context.cookieApi.getCookie(cookieUrl)).length > 0 : false;
  const hasLoginInfo = text(context.sourceApi.getLoginInfo()).length > 0;
  return { loggedIn: hasCookie || hasLoginInfo, message: hasCookie ? 'Cookie 已存在' :
    (hasLoginInfo ? '登录信息已保存' : '尚未登录') };
};

module.exports.manageSearchTarget = async input => {
  const sourceKey = text(input.sourceKey).trim();
  const action = text(input.action).trim();
  const databaseSource = databaseSourceByKey(sourceKey);
  if (databaseSource) {
    if (action === 'disable') {
      databaseSource.enabled = false;
      if (!databaseExecute(
        'UPDATE legado_sources SET enabled = 0, source_json = ?, updated_at_ms = ? WHERE source_key = ?',
        [JSON.stringify(databaseSource), Date.now(), sourceKey])) return { changed: false };
    } else if (action === 'delete') {
      const prefix = sourceStorageKey(databaseSource, '');
      ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
      if (!databaseExecute('DELETE FROM legado_sources WHERE source_key = ?', [sourceKey])) {
        return { changed: false };
      }
    } else {
      throw new Error('不支持的书源处理动作');
    }
    const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
      reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
    if (active === sourceKey) {
      reader.storage.set(ACTIVE_SOURCE_KEY, '');
      reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
      reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
    }
    return { changed: true };
  }
  const sources = importedSources();
  const index = sources.findIndex(item =>
    text(item.bookSourceUrl || item.bookSourceName) === sourceKey);
  if (index < 0) return { changed: false };
  if (action === 'disable') {
    sources[index] = Object.assign({}, sources[index], { enabled: false });
  } else if (action === 'delete') {
    const source = sources[index];
    sources.splice(index, 1);
    const prefix = sourceStorageKey(source, '');
    ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
  } else {
    throw new Error('不支持的书源处理动作');
  }
  reader.storage.set(SOURCE_KEY, sources);
  reader.storage.set(LEGACY_SOURCE_KEY, []);
  const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) || reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
  if (active === sourceKey) {
    reader.storage.set(ACTIVE_SOURCE_KEY, '');
    reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
    reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
  }
  return { changed: true };
};

module.exports.manage = async input => {
  const mode = text(input.mode);
  if (mode === 'deleteSources') {
    const sourceKeys = [...new Set((Array.isArray(input.sourceKeys) ? input.sourceKeys : [])
      .map(value => text(value).trim()).filter(Boolean))];
    if (!sourceKeys.length || sourceKeys.length > 5000) throw new Error('批量删除书源数量无效');
    if (input.deleteAll === true) {
      if (!databaseExecute('DELETE FROM legado_sources', [])) {
        throw new Error('清空书源数据库失败');
      }
    } else if (reader.database && typeof reader.database.batch === 'function') {
      for (let offset = 0; offset < sourceKeys.length; offset += 500) {
        reader.database.batch({ statements: sourceKeys.slice(offset, offset + 500).map(sourceKey => ({
          sql: 'DELETE FROM legado_sources WHERE source_key = ?', bindArgs: [sourceKey]
        })) });
      }
    } else {
      sourceKeys.forEach(sourceKey => {
        if (!databaseExecute('DELETE FROM legado_sources WHERE source_key = ?', [sourceKey])) {
          throw new Error('删除书源失败：' + sourceKey);
        }
      });
    }
    const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
      reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
    if (sourceKeys.includes(active)) {
      reader.storage.set(ACTIVE_SOURCE_KEY, '');
      reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
      reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
    }
    return { deleted: sourceKeys.length, runtimeCleanupPending: sourceKeys.length };
  }
  if (mode === 'cleanupDeletedSources') {
    const sourceKeys = [...new Set((Array.isArray(input.sourceKeys) ? input.sourceKeys : [])
      .map(value => text(value).trim()).filter(Boolean))];
    if (!sourceKeys.length || sourceKeys.length > 50) throw new Error('清理书源数量无效');
    sourceKeys.forEach(sourceKey => {
      const prefix = sourceStorageKey({ bookSourceUrl: sourceKey }, '');
      ['loginInfo', 'loginHeader', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
    });
    return { cleaned: sourceKeys.length };
  }
  if (mode === 'validateSource') {
    const sourceKey = text(input.sourceKey).trim();
    const source = sourceByKey(sourceKey);
    return validateSourceForManagement(source, input);
  }
  const sourceKey = text(input.sourceKey);
  const sourceTts = databaseHttpTtsByKey(sourceKey);
  const source = sourceByKey(sourceKey) ||
    (sourceTts ? httpTtsRuntimeSource(sourceTts.record, sourceTts.key) : null);
  if (!source) throw new Error('书源不存在或已被删除');
  if (mode === 'getLoginInfo') {
    return jsonObject(reader.storage.get(sourceStorageKey(source, 'loginInfo')), {});
  }
  if (mode === 'getLoginUi') return evaluateLoginUi(source, input);
  if (mode === 'getLoginLabels') return evaluateLoginLabels(source, input);
  if (mode === 'deleteSource') {
    const prefix = sourceStorageKey(source, '');
    ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
    return { deleted: true };
  }
  if (mode === 'loginAction') return executeLoginAction(source, input);
  throw new Error('不支持的插件管理操作');
};
